SELECT ss.store_id, DATE_FORMAT(ss.sale_date, 'yyyy-MM') AS sale_month, MAX(i.last_restock) AS last_last_restock, AVG(i.quantity) AS avg_quantity FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id GROUP BY ss.store_id, DATE_FORMAT(ss.sale_date, 'yyyy-MM') ORDER BY avg_quantity;
